Mesh<Point, double> result;

  for (auto it = rt.finite_facets_begin(); it != rt.finite_facets_end(); ++it) {
    if (!is_large_facet(rt, *it, threshold)) {
      continue;
    }

    RT::Cell_handle cell = it->first;
    int index = it->second;

    RT::Vertex_handle v1 = cell->vertex(0);
    RT::Vertex_handle v2 = cell->vertex(1);
    RT::Vertex_handle v3 = cell->vertex(2);
    RT::Vertex_handle v4 = cell->vertex(3);

    // Determine the vertices of the facet (in dual space)
    RT::Vertex_handle v_opposite = cell->vertex(index);
    std::vector<RT::Vertex_handle> vs{v1, v2, v3, v4};
    vs.erase(std::remove(vs.begin(), vs.end(), v_opposite), vs.end());

    // Add the three edges of the facet to the mesh
    for (int i = 0; i < 3; ++i) {
      for (int j = i + 1; j < 3; ++j) {
        Point p1 = rt.dual(vs[i]->cell(0));
        Point p2 = rt.dual(vs[j]->cell(0));
        result.add(p1, p2, 0.0);
      }
    }
  }

  return result;

